            new CyberwareDef { Name = "Демпфер", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6/2 (2)", Requires = "Набор кибераудио", Description = "Автоматическая компенсация шума. Пользователь невосприимчив к глухоте или другим эффектам, вызванным опасно громкими звуками, например, от светошумовой гранаты. Требует набор кибераудио." },
            new CyberwareDef { Name = "Детектор жучков", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6/2 (2)", Requires = "Набор кибераудио", Description = "Подает звуковой сигнал, когда пользователь находится в пределах 2 м от прослушки, жучка или другого подслушивающего устройства. Требует набор кибераудио." },
            new CyberwareDef { Name = "Диктофон", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6/2 (2)", Requires = "Набор кибераудио", Description = "Записывает звук на стандартный чип памяти или на связанный Агент. Требует набор кибераудио." },
            new CyberwareDef { Name = "Радар-детектор", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6/2 (2)", Requires = "Набор кибераудио", Description = "Подает звуковой сигнал, если в пределах 100 м присутствует активный луч радара. Требует набор кибераудио." },
            new CyberwareDef { Name = "Радиокоммуникатор", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6/2 (2)", Requires = "Набор кибераудио", Description = "Пользователь может общаться по радио, радиус действия 1.6 км. Требует набор кибераудио." },
            new CyberwareDef { Name = "Радиосканер/музыкальный плеер", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6/2 (2)", Requires = "Набор кибераудио", Description = "Пользователь может использовать действие, чтобы просканировать все радиодиапазоны в пределах 1.6 км, которые используются в данный момент, и настроиться на них. Музыкальный плеер может подключаться к ДатаПулу, чтобы слушать самые горячие хиты, или воспроизводить музыку напрямую с щепки памяти. Для понимания зашифрованных каналов требуется Шифратор/Дешифратор. Требует набор кибераудио." },
            new CyberwareDef { Name = "Трекер", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6/2 (2)", Requires = "Набор кибераудио", Description = "Может отслеживать связанный маячок на расстоянии до 1.6 км. В комплект входит один бесплатный связанный маячок размером с кнопку. Замена стоит 50eb. Требует набор кибераудио." },
            new CyberwareDef { Name = "Усиленный слух", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6 (3)", Requires = "Набор кибераудио", Description = "+2 к проверкам восприятия, связанным со слухом. Не суммируется при повторной установке. Требует набор кибераудио.",
                SkillModifiers = new List<SkillModifierDef> { new SkillModifierDef { SkillName = "Внимательность", Value = 2, ModType = "Audio" } } },
            new CyberwareDef { Name = "Шифратор/дешифратор", Category = "КИБЕРАУДИО (CYBERAUDIO)", Slots = 1, HumanityLoss = "1d6/2 (2)", Requires = "Набор кибераудио", Description = "Позволяет пользователю шифровать исходящие сообщения, чтобы их нельзя было понять без дешифратора, который также включен в комплект без дополнительной платы. Требует набор кибераудио." },

            // ================== ВНУТРЕННИЕ ИМПЛАНТЫ ==================
            new CyberwareDef { Name = "АудиоВокс", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Синтезатор голоса. Пользователь добавляет +2 к навыку актерское мастерство, а также +2 к навыку игра на инструменте во время пения. Повторная установка не дает дополнительных преимуществ.",
                SkillModifiers = new List<SkillModifierDef> { new SkillModifierDef { SkillName = "Актерское мастерство", Value = 2 }, new SkillModifierDef { SkillName = "Игра на инструментах", Value = 2 } } },
            new CyberwareDef { Name = "Вампиры", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "4d6 (14)", Description = "Клыки, вживленные в рот. Легкое холодное оружие отличного качества (урон 1d6, 2 СКОР), скрываемое без проверки. В небе рта есть отсек для яда или биотоксина (покупается отдельно, стр. 360), который наносится на клыки без использования действия. Одной порции хватает на 30 минут. Установка включает полную переделку рта, так что ты не отравишься сам, когда ешь пиццу." },
            new CyberwareDef { Name = "Жабры", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "2d6 (7)", Description = "Позволяют дышать под водой." },
            new CyberwareDef { Name = "Искусственные мышцы и усиленные кости", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "4d6 (14)", Description = "Ты увеличиваешь характеристику ТЕЛО на 2. Это изменение влияет на твои ПЗ, Порог ранения и Спасбросок от смерти. Эффекты от не скольких установок суммируются, но нельзя поднять ТЕЛО выше 10." },
            new CyberwareDef { Name = "Киберзмей", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "4d6 (14)", Description = "Ужасающее оружие-щупальце, вмонтированное в горло/пищевод. Считается очень тяжелым холодным оружием (4d6, 1 СКОР), которое можно успешно скрыть без проверки." },
            new CyberwareDef { Name = "Контрацептивный имплант", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "0 (—)", Description = "Предотвращает нежелательную беременность." },
            new CyberwareDef { Name = "Назальные фильтры", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "1d6/2 (2)", Description = "У тебя иммунитет к воздействию токсичных газов, паров и подобных опасностей, которые должны быть втянуты носом. Ты можешь отключить фильтры по желанию без использования действия." },
            new CyberwareDef { Name = "Независимый запас воздуха", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "1d6/2 (2)", Description = "Содержит запас воздуха на 30 минут. После этого баллон нужно заправить из окружающей среды, что занимает час. Замена пустого баллона на полный (50eb) занимает 1 действие." },
            new CyberwareDef { Name = "Радар/сонар-имплант", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "2d6 (7)", Description = "Постоянно сканирует местность в радиусе 50 м на наличие новых угроз, включая подводные объекты. Сканирование не видит то, что находится за укрытием (например, содержимое комнаты за закрытой дверью). Рефери подает тебе звуковой сигнал и указывает направление, когда обнаруживается новый движущийся объект. Повторная установка не дает преимуществ." },
            new CyberwareDef { Name = "Связыватели токсинов", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "1d6/2 (2)", Description = "+2 к проверкам сопротивления пыткам/наркотикам. Повторная установка не дает преимуществ.",
                SkillModifiers = new List<SkillModifierDef> { new SkillModifierDef { SkillName = "Сопр. пыткам/наркотикам", Value = 2 } } },
            new CyberwareDef { Name = "Сексуальный имплант Мистер Перчик", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "2d6 (7)", Description = "Всю ночь, каждую ночь. И никто не узнает." },
            new CyberwareDef { Name = "Сексуальный имплант Полуночница", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "2d6 (7)", Description = "Будь Венерой, будь огнём, будь желанием." },
            new CyberwareDef { Name = "Усиленные антитела", Category = "ВНУТРЕННИЕ ИМПЛАНТЫ (INTERNAL)", Slots = 1, HumanityLoss = "1d6/2 (2)", Description = "После стабилизации ты восстанавливаешь количество ПЗ, равное твоему ТЕЛО, умноженному на два, за каждый день отдыха или легкой активности. Это заменяет твою обычную скорость исцеления." },

            // ================== ВНЕШНИЕ ИМПЛАНТЫ ==================
            new CyberwareDef { Name = "Плетёная кожа", Category = "ВНЕШНИЕ ИМПЛАНТЫ (EXTERNAL)", Slots = 1, HumanityLoss = "2d6 (7)", Description = "Твое тело и голова защищены броней с показателем ОС7. Твоя ОС в любом месте определяется самым высоким источником ОС в этой локации. Кроме того, когда твоя броня подвергается разрушению где либо, все твои источники ОС в этом месте разрушаются одновременно. Всякий раз, когда ты успешно завершаешь день естественного исцеления, наномашины, присутствующие в Плетёной коже, восстанавливают по одному пункту потерянного ОС как тела, так и головы." },
            new CyberwareDef { Name = "Подкожная броня", Category = "ВНЕШНИЕ ИМПЛАНТЫ (EXTERNAL)", Slots = 1, HumanityLoss = "4d6 (14)", Description = "Твое тело и голова защищены броней с показателем ОС11. Твоя ОС в любом месте определяется самым высоким источником ОС в этом месте. Кроме того, когда твоя броня подвергается разрушению где либо, все твои источники ОС в этом месте разрушаются одновременно. Всякий раз, когда ты успешно завершаешь день естественного исцеления, наномашины в подкожной броне восстанавливают по одному пункту потерянного ОС как тела, так и головы." },
            new CyberwareDef { Name = "Подкожный карман", Category = "ВНЕШНИЕ ИМПЛАНТЫ (EXTERNAL)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Пространство размером 5 см x 10 см с застежкой-молнией Realskinn™. Содержимое можно успешно скрыть без проверки." },
            new CyberwareDef { Name = "Скрытая кобура", Category = "ВНЕШНИЕ ИМПЛАНТЫ (EXTERNAL)", Slots = 1, HumanityLoss = "2d6 (7)", Description = "Кобура внутри твоего тела может хранить оружие, которое уже пригодно для скрытого ношения, так что его можно успешно спрятать без броска. Оружие можно достать из скры- той кобуры без использования действия, если она имплантирована в легкодоступном месте на твоем теле. Тебе вряд ли захочется ставить ее в бедро, если ты не носишь штаны." },

            // ================== КИБЕРРУКИ (ПРАВАЯ) ==================
            new CyberwareDef { Name = "Киберрука", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 0, HumanityLoss = "2d6 (7)", IsFoundation = true, Description = "Протез руки. Имеет 4 слота опций. Поставляется со стандартной кистью, не вызывающей потерю человечности и не занимающей слот." },
            new CyberwareDef { Name = "Стандартная кисть", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 0, HumanityLoss = "1d6/2 (2)", Description = "Выглядит как обычная человеческая кисть. Если установлена в биоруку, не считается в лимит киберимплантов, размещённых в биоконечности. Не занимает слот опций для киберруки." },
            new CyberwareDef { Name = "Большие костяшки", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Бронированные кастеты. Среднее холодное оружие (2d6 урона, СКОР 2), которое можно скрыть без проверки. При использовании как оружие пользователь не может держать что-либо этой рукой. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Быстросъёмное крепление", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Киберрука может устанавливаться в открытый разъём и сниматься Действием. При первой установке новой киберруки (через быстросъёмное крепление или иначе) всегда начисляется потеря человечности. Повторная установка уже использованной руки через быстросъёмное крепление её не вызывает." },
            new CyberwareDef { Name = "Выкидное дальнобойное оружие", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Одноручное дальнобойное оружие (не обязано быть скрываемым до установки), предоставленное пользователем, встраивается в киберруку вместе с установленными на нём приспособлениями для оружия. Можно скрыть без проверки, извлекать и убирать без действия. В разложенном состоянии пользователь не может держать что-либо этой рукой. Требует киберруку и занимает 2 слота опций." },
            new CyberwareDef { Name = "Выкидное холодное оружие", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Одноручное лёгкое, среднее или тяжёлое холодное оружие (не обязано быть скрываемым до установки) встраивается в киберруку. Можно скрыть без броска и извлекать/убирать без действия. В разложенном состоянии пользователь не может держать что-либо этой рукой. Требует киберруку и занимает 2 слота опций." },
            new CyberwareDef { Name = "Выкидной гранатомёт", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Одноручный гранатомёт с одним снарядом, несовмести- мый со всеми приспособлениями для оружия, кроме интерфейса умного оружия, встраивается в киберруку. Можно скрыть без проверки, извлекать и убирать без действия. В разложенном состоянии пользователь не может дер- жать что-либо этой рукой. Требует киберруку и занимает 2 слота опций." },
            new CyberwareDef { Name = "Выкидной щит", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 3, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Пуленепробиваемый щит складывается внутри киберруки. Можно извлекать и убирать без действия, если у щита больше 0 ПЗ. В разложенном состоянии киберрука может использоваться только как щит. Пользователь не может держать ничего, кроме него. Щит легко извлекается для чистки или замены. См. правила использования щитов в разделе Бой, стр. 183. Требует киберруку и занимает 3 слота опций." },
            new CyberwareDef { Name = "Грейферная рука", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "1d6 (3)", Requires = "Киберрука", Description = "Действием пользователь выстреливает реактивным гарпуном, который цепляется за толстое укрытие на дистанции до 30 м. Трос выдерживает вес до двукратного веса пользователя и имеет 10 ПЗ. Пользователь игнорирует стандартный штраф за перемещение при лазании и может втянуть трос без действия, в том числе во время подъёма. В разложенном состоянии пользователь не может дер- жать что-либо этой рукой. Неэффективен как оружие и не может использоваться для захвата. Требует киберруку." },
            new CyberwareDef { Name = "Кибердека", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 3, HumanityLoss = "1d6 (3)", Requires = "Киберрука", Description = "Кибердека навсегда встраивается в киберруку. Деку предоставляет пользователь при установке. Помимо защиты от потери, интеграция даёт кибердеке +1 дополнительный слот, который можно использовать для программ или железа. Улучшение постоянное. Попытка извлечь деку разрушает её без возможности ремонта (программы и железо можно спасти). Требует киберруку, интерфейсный разъём и нейролинк и занимает 3 слота опций." },
            new CyberwareDef { Name = "Когти", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "2d6 (7)", Description = "Выдвижные когти из карбостекла в костяшках. Тяжёлое холодное оружие (3d6 урона, СКОР 2), скрывается без проверки. При использовании как оружие пользователь не может держать что-либо этой рукой. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Медсканер", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Медсканер, установленный в киберруку. Сканер с внешними датчиками диагностирует травмы и болезни, позволяя оказывать неотложную помощь без навыка хирургии. +2 к первой помощи и парамедицине. Требует киберруку и занимает 2 слота опций.",
                SkillModifiers = new List<SkillModifierDef> { new SkillModifierDef { SkillName = "Первая помощь", Value = 2 }, new SkillModifierDef { SkillName = "Парамедик (x2)", Value = 2 } } },
            new CyberwareDef { Name = "Наплечная камера", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Камера в выдвижном модуле на плече, автономно отслеживает цель и записывает видео и аудио на щепку памяти или связанный агент. Можно скрыть без проверки, извлекать и убирать без действия. Требует киберруку и занимает 2 слота опций." },
            new CyberwareDef { Name = "Подкожный захват", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "1d6 (3)", Requires = "Нейролинк", Description = "Нейроимплант. Подкожная пластина в ладони позволяет использовать умное оружие. Более дешёвая альтернатива интерфейсного разъ- ёма. Может быть установлен как единственный киберимплант в биоруке. Требует нейролинк и занимает слот опции нейроимпланта. Требует нейролинк." },
            new CyberwareDef { Name = "Потрошители", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Опция киберруки. Выдвижные когти из карбостекла. Среднее холодное оружие (2d6 урона, СКОР 2), скрывается без проверки. При использовании как оружие пользователь не может держать что-либо этой рукой. Может быть установлен как единственный киберимплант в биоруке. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Резать и рубить", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Монофиламентный хлыст, встроенный в большой палец. Среднее холодное оружие (2d6 урона, СКОР 2), скрывается без проверки. При использовании как оружие пользователь не может держать что-либо этой рукой. Может быть установлен как единственный киберимплант в биоруке. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Рука мультитул", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Пальцы содержат отвёртку, гаечный ключ, мини- дрель и другие инструменты. Ты всегда с инструментом. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Техсканер", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Сканер анализирует технику и электронику, помогая в ремонте и технической работе. Пользователь получает +2 к навыкам: Основы техники, Кибертехника, Автомеханика, Судоремонт, Авиатехника, Электроника/ Безопасность, Оружейная техника. Требует киберруку и занимает 2 слота опций. Повторная установка не даёт дополнительных преимуществ.",
                SkillModifiers = new List<SkillModifierDef> { new SkillModifierDef { SkillName = "Знание техники", Value = 2 }, new SkillModifierDef { SkillName = "Кибертехника", Value = 2 }, new SkillModifierDef { SkillName = "Автомеханика", Value = 2 }, new SkillModifierDef { SkillName = "Морские технологии", Value = 2 }, new SkillModifierDef { SkillName = "Авиационные технологии", Value = 2 }, new SkillModifierDef { SkillName = "Электроника/Безопасность (x2)", Value = 2 }, new SkillModifierDef { SkillName = "Оружейник", Value = 2 } } },
            new CyberwareDef { Name = "Царапки", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "1d6/2 (2)", Description = "Ногти из карбостекла с диагональным резом. Лёгкое холодное оружие (1d6 урона, СКОР 2), скрывается без проверки. При использовании как оружие по льзо- ватель не может держать что-либо этой рукой. Может быть установлен как единственный киберимплант в биоруке. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Закалённое экранирование", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 1, HumanityLoss = "1d6 (3)", Requires = "Киберрука", Description = "Опция киберконечности. Киберконечность и её установленные опции не выводятся из строя эффектами ЭМИ (например, микроволновыми импульсами) или эффектами программ, не относящихся к Чёрному Льду. Требует киберруку или киберногу." },
            new CyberwareDef { Name = "Пластиковое покрытие", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 0, HumanityLoss = "0 (—)", Requires = "Киберрука", Description = "Опция киберконечности. Пластиковое покрытие. Доступно в широком диапазоне цве- тов и узоров. Требует киберруку или киберногу, но не занимает слот опций." },
            new CyberwareDef { Name = "Покрытие Realskinn", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 0, HumanityLoss = "0 (—)", Requires = "Киберрука", Description = "Опция киберконечности. Искусственная кожа для киберконечности. Требует киберруку или киберногу, но не занимает слот опций." },
            new CyberwareDef { Name = "Покрытие Superchrome", Category = "ПРАВАЯ КИБЕРРУКА (CYBERARM R)", Slots = 0, HumanityLoss = "0 (—)", Requires = "Киберрука", Description = "Опция киберконечности. Блестящее металлическое покрытие для киберконечности. +2 к гардеробу и стилю. Требует киберруку или киберногу, но не занимает слот опций.",
                SkillModifiers = new List<SkillModifierDef> { new SkillModifierDef { SkillName = "Гардероб и стиль", Value = 2 } } },

            // ================== КИБЕРРУКИ (ЛЕВАЯ) ==================
            new CyberwareDef { Name = "Киберрука", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 0, HumanityLoss = "2d6 (7)", IsFoundation = true, Description = "Протез руки. Имеет 4 слота опций. Поставляется со стандартной кистью, не вызывающей потерю человечности и не занимающей слот." },
            new CyberwareDef { Name = "Стандартная кисть", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 0, HumanityLoss = "1d6/2 (2)", Description = "Выглядит как обычная человеческая кисть. Если установлена в биоруку, не считается в лимит киберимплантов, размещённых в биоконечности. Не занимает слот опций для киберруки." },
            new CyberwareDef { Name = "Большие костяшки", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Бронированные кастеты. Среднее холодное оружие (2d6 урона, СКОР 2), которое можно скрыть без проверки. При использовании как оружие пользователь не может держать что-либо этой рукой. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Быстросъёмное крепление", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 1, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Киберрука может устанавливаться в открытый разъём и сниматься Действием. При первой установке новой киберруки (через быстросъёмное крепление или иначе) всегда начисляется потеря человечности. Повторная установка уже использованной руки через быстросъёмное крепление её не вызывает." },
            new CyberwareDef { Name = "Выкидное дальнобойное оружие", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Одноручное дальнобойное оружие (не обязано быть скрываемым до установки), предоставленное пользователем, встраивается в киберруку вместе с установленными на нём приспособлениями для оружия. Можно скрыть без проверки, извлекать и убирать без действия. В разложенном состоянии пользователь не может держать что-либо этой рукой. Требует киберруку и занимает 2 слота опций." },
            new CyberwareDef { Name = "Выкидное холодное оружие", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Одноручное лёгкое, среднее или тяжёлое холодное оружие (не обязано быть скрываемым до установки) встраивается в киберруку. Можно скрыть без броска и извлекать/убирать без действия. В разложенном состоянии пользователь не может держать что-либо этой рукой. Требует киберруку и занимает 2 слота опций." },
            new CyberwareDef { Name = "Выкидной гранатомёт", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Одноручный гранатомёт с одним снарядом, несовмести- мый со всеми приспособлениями для оружия, кроме интерфейса умного оружия, встраивается в киберруку. Можно скрыть без проверки, извлекать и убирать без действия. В разложенном состоянии пользователь не может дер- жать что-либо этой рукой. Требует киберруку и занимает 2 слота опций." },
            new CyberwareDef { Name = "Выкидной щит", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 3, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Пуленепробиваемый щит складывается внутри киберруки. Можно извлекать и убирать без действия, если у щита больше 0 ПЗ. В разложенном состоянии киберрука может использоваться только как щит. Пользователь не может держать ничего, кроме него. Щит легко извлекается для чистки или замены. См. правила использования щитов в разделе Бой, стр. 183. Требует киберруку и занимает 3 слота опций." },
            new CyberwareDef { Name = "Грейферная рука", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 1, HumanityLoss = "1d6 (3)", Requires = "Киберрука", Description = "Действием пользователь выстреливает реактивным гарпуном, который цепляется за толстое укрытие на дистанции до 30 м. Трос выдерживает вес до двукратного веса пользователя и имеет 10 ПЗ. Пользователь игнорирует стандартный штраф за перемещение при лазании и может втянуть трос без действия, в том числе во время подъёма. В разложенном состоянии пользователь не может дер- жать что-либо этой рукой. Неэффективен как оружие и не может использоваться для захвата. Требует киберруку." },
            new CyberwareDef { Name = "Кибердека", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 3, HumanityLoss = "1d6 (3)", Requires = "Киберрука", Description = "Кибердека навсегда встраивается в киберруку. Деку предоставляет пользователь при установке. Помимо защиты от потери, интеграция даёт кибердеке +1 дополнительный слот, который можно использовать для программ или железа. Улучшение постоянное. Попытка извлечь деку разрушает её без возможности ремонта (программы и железо можно спасти). Требует киберруку, интерфейсный разъём и нейролинк и занимает 3 слота опций." },
            new CyberwareDef { Name = "Когти", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 1, HumanityLoss = "2d6 (7)", Description = "Выдвижные когти из карбостекла в костяшках. Тяжёлое холодное оружие (3d6 урона, СКОР 2), скрывается без проверки. При использовании как оружие пользователь не может держать что-либо этой рукой. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Медсканер", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Медсканер, установленный в киберруку. Сканер с внешними датчиками диагностирует травмы и болезни, позволяя оказывать неотложную помощь без навыка хирургии. +2 к первой помощи и парамедицине. Требует киберруку и занимает 2 слота опций.",
                SkillModifiers = new List<SkillModifierDef> { new SkillModifierDef { SkillName = "Первая помощь", Value = 2 }, new SkillModifierDef { SkillName = "Парамедик (x2)", Value = 2 } } },
            new CyberwareDef { Name = "Наплечная камера", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Камера в выдвижном модуле на плече, автономно отслеживает цель и записывает видео и аудио на щепку памяти или связанный агент. Можно скрыть без проверки, извлекать и убирать без действия. Требует киберруку и занимает 2 слота опций." },
            new CyberwareDef { Name = "Подкожный захват", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 1, HumanityLoss = "1d6 (3)", Requires = "Нейролинк", Description = "Нейроимплант. Подкожная пластина в ладони позволяет использовать умное оружие. Более дешёвая альтернатива интерфейсного разъ- ёма. Может быть установлен как единственный киберимплант в биоруке. Требует нейролинк и занимает слот опции нейроимпланта. Требует нейролинк." },
            new CyberwareDef { Name = "Потрошители", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Опция киберруки. Выдвижные когти из карбостекла. Среднее холодное оружие (2d6 урона, СКОР 2), скрывается без проверки. При использовании как оружие пользователь не может держать что-либо этой рукой. Может быть установлен как единственный киберимплант в биоруке. Может быть единственным киберимплантом в мясной руке." },
