            new CyberwareDef { Name = "Рука мультитул", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 1, HumanityLoss = "1d6 (3)", Description = "Пальцы содержат отвёртку, гаечный ключ, мини- дрель и другие инструменты. Ты всегда с инструментом. Может быть единственным киберимплантом в мясной руке." },
            new CyberwareDef { Name = "Техсканер", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 2, HumanityLoss = "2d6 (7)", Requires = "Киберрука", Description = "Сканер анализирует технику и электронику, помогая в ремонте и технической работе. Пользователь получает +2 к навыкам: Основы техники, Кибертехника, Автомеханика, Судоремонт, Авиатехника, Электроника/ Безопасность, Оружейная техника. Требует киберруку и занимает 2 слота опций. Повторная установка не даёт дополнительных преимуществ.",
