            new CyberwareDef { Name = "Закалённое экранирование", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 1, HumanityLoss = "1d6 (3)", Requires = "Киберрука", Description = "Опция киберконечности. Киберконечность и её установленные опции не выводятся из строя эффектами ЭМИ (например, микроволновыми импульсами) или эффектами программ, не относящихся к Чёрному Льду. Требует киберруку или киберногу." },
            new CyberwareDef { Name = "Пластиковое покрытие", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 0, HumanityLoss = "0 (—)", Requires = "Киберрука", Description = "Опция киберконечности. Пластиковое покрытие. Доступно в широком диапазоне цве- тов и узоров. Требует киберруку или киберногу, но не занимает слот опций." },
            new CyberwareDef { Name = "Покрытие Realskinn", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 0, HumanityLoss = "0 (—)", Requires = "Киберрука", Description = "Опция киберконечности. Искусственная кожа для киберконечности. Требует киберруку или киберногу, но не занимает слот опций." },
            new CyberwareDef { Name = "Покрытие Superchrome", Category = "ЛЕВАЯ КИБЕРРУКА (CYBERARM L)", Slots = 0, HumanityLoss = "0 (—)", Requires = "Киберрука", Description = "Опция киберконечности. Блестящее металлическое покрытие для киберконечности. +2 к гардеробу и стилю. Требует киберруку или киберногу, но не занимает слот опций.",
