            // ================== КИБЕРНОГИ (ПРАВАЯ) ==================
            new CyberwareDef { Name = "Кибернога", Category = "ПРАВАЯ КИБЕРНОГА (CYBERLEG R)", Slots = 0, HumanityLoss = "1d6 (3)", IsFoundation = true, Description = "Протез ноги. Не требует парной установки. У киберноги есть 3 ячейки для опций кибер- ноги или киберконечности, каждая изначально оснащена стандартной ступнёй, которая не вызывает Потери Человечности и не занимает ячейку опции киберноги. Большинство опций киберноги требуют парной установки (покупаются дважды и устанавливаются в две разные киберноги). Потеря человечности рассчитывается отдельно за каждую покупку." },
            new CyberwareDef { Name = "Стандартная стопа", Category = "ПРАВАЯ КИБЕРНОГА (CYBERLEG R)", Slots = 0, HumanityLoss = "1d6/2 (2)", Description = "Выглядит как обычная ступня. При установке в «мясную» ногу не учитывается в общем количестве киберимплантов, установленных в неё. Не занимает ячейку опции киберноги." },
